-- Objective 5A: turn the existing interactive catalogue into the single,
-- traceable mathematical specification. Complex methods intentionally remain
-- not_implemented; validation status is independent from runtime status.

update public.calculation_definitions as c
set method_version = v.method_version,
    definition = v.definition,
    updated_at = now()
from (values
  ('bmi', '1.1.0', $json${
    "catalogVersion":2,"resultKey":"bmi","resultName":"Índice de masa corporal","methodName":"IMC","method":"Índice de Quetelet","variant":"peso/talla²","summary":"Relaciona el peso medido en la consulta con la estatura del expediente.","unit":"kg/m²","decimalPlaces":1,
    "inputs":[{"key":"weight","label":"Peso","source":"consultation_measurement","measurementCode":"weight","expectedUnit":"kg"},{"key":"height","label":"Estatura","source":"patient_record","patientField":"height_cm","expectedUnit":"cm"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"IMC = peso_kg / (estatura_cm / 100)²","variables":{"peso_kg":"Peso de la consulta en kg","estatura_cm":"Estatura del expediente en cm"},"transformations":["Convertir estatura de cm a m antes de elevar al cuadrado"]},"variants":[],
    "applicability":{"population":"Índice descriptivo para adultos; este contrato no aplica clasificación clínica.","notes":["La interpretación depende del contexto clínico y no forma parte de este objetivo."]},
    "references":[{"authors":"World Health Organization","year":2000,"title":"Obesity: preventing and managing the global epidemic","source":"WHO Technical Report Series 894","url":"https://iris.who.int/handle/10665/42330","evidence":"technical_manual"}],
    "validationStatus":"validated","validationNote":"Ecuación, unidades y fuentes de datos confirmadas.","methodologicalNotes":["La estatura procede del expediente y el peso debe existir en la consulta."],"limitations":"Es un índice descriptivo; no representa composición corporal ni diagnóstico."
  }$json$::jsonb),
  ('waist_hip_ratio', '1.1.0', $json${
    "catalogVersion":2,"resultKey":"waist_hip_ratio","resultName":"Índice cintura/cadera","methodName":"Relación cintura/cadera","method":"Waist-to-hip ratio","variant":"cintura ÷ cadera","summary":"Relaciona la circunferencia de cintura con la circunferencia máxima de cadera/glúteo de la misma consulta.","unit":"razón","decimalPlaces":2,
    "inputs":[{"key":"waist","label":"Circunferencia de cintura","source":"consultation_measurement","measurementCode":"waist_circumference","expectedUnit":"cm"},{"key":"hip","label":"Circunferencia de cadera/glúteo","source":"consultation_measurement","measurementCode":"hip_circumference","expectedUnit":"cm"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"ICC = cintura_cm / cadera_cm","variables":{"cintura_cm":"Circunferencia de cintura en cm","cadera_cm":"Circunferencia máxima de cadera/glúteo en cm"}},"variants":[],
    "applicability":{"population":"Adultos medidos con sitios anatómicos consistentes.","notes":["No equivale a circunferencia abdominal."]},
    "references":[{"authors":"World Health Organization","year":2008,"title":"Waist circumference and waist-hip ratio: report of a WHO expert consultation","source":"WHO","url":"https://iris.who.int/handle/10665/44583","evidence":"technical_manual"}],
    "validationStatus":"validated","validationNote":"Razón y sitios anatómicos definidos.","methodologicalNotes":["Ambas circunferencias deben pertenecer a la consulta actual."],"limitations":"No se aplican puntos de corte ni interpretación clínica en este objetivo."
  }$json$::jsonb),
  ('waist_height_ratio', '1.1.0', $json${
    "catalogVersion":2,"resultKey":"waist_height_ratio","resultName":"Índice cintura/talla","methodName":"Relación cintura/talla","method":"Waist-to-height ratio","variant":"cintura ÷ talla","summary":"Relaciona la circunferencia de cintura de la consulta con la estatura del expediente.","unit":"razón","decimalPlaces":2,
    "inputs":[{"key":"waist","label":"Circunferencia de cintura","source":"consultation_measurement","measurementCode":"waist_circumference","expectedUnit":"cm"},{"key":"height","label":"Estatura","source":"patient_record","patientField":"height_cm","expectedUnit":"cm"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"ICT = cintura_cm / estatura_cm","variables":{"cintura_cm":"Circunferencia de cintura en cm","estatura_cm":"Estatura en cm"}},"variants":[],
    "applicability":{"population":"Índice antropométrico descriptivo; mediciones expresadas en la misma unidad."},
    "references":[{"authors":"Ashwell M, Hsieh SD","year":2005,"title":"Six reasons why the waist-to-height ratio is a rapid and effective global indicator for health risks of obesity","source":"International Journal of Food Sciences and Nutrition","doi":"10.1080/09637480500195066","url":"https://pubmed.ncbi.nlm.nih.gov/16236591/","evidence":"original"}],
    "validationStatus":"validated","validationNote":"Razón, unidades y fuentes de datos definidas.","methodologicalNotes":["No se aplican umbrales clínicos."],"limitations":"No se aplican puntos de corte ni interpretación clínica en este objetivo."
  }$json$::jsonb),
  ('density_jackson_pollock_3', '2.0.0-spec', $json${
    "catalogVersion":2,"resultKey":"body_density","resultName":"Densidad corporal","methodName":"Jackson & Pollock 3","method":"Jackson-Pollock generalizado","variant":"Tres pliegues, específica por sexo","summary":"Estima densidad corporal mediante tres pliegues seleccionados según el sexo para ecuaciones y la edad en la consulta.","unit":"g/cm³","decimalPlaces":5,
    "inputs":[{"key":"sex","label":"Sexo para ecuaciones","source":"patient_record","patientField":"equation_sex","expectedUnit":"categoría"},{"key":"age","label":"Edad en esta consulta","source":"patient_derived","derivation":"age_at_consultation","expectedUnit":"años"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"La ecuación activa depende del sexo para ecuaciones; S3 es la suma de tres pliegues en mm."},
    "variants":[
      {"code":"male","name":"Masculina · pectoral, abdominal y muslo anterior","appliesWhen":{"equationSex":"male"},"inputs":[{"key":"chest","label":"Pliegue pectoral","source":"consultation_measurement","measurementCode":"chest_skinfold","expectedUnit":"mm"},{"key":"abdominal","label":"Pliegue abdominal","source":"consultation_measurement","measurementCode":"abdominal_skinfold","expectedUnit":"mm"},{"key":"thigh","label":"Pliegue de muslo anterior","source":"consultation_measurement","measurementCode":"thigh_skinfold","expectedUnit":"mm"}],"equation":{"expression":"D = 1.10938 − 0.0008267·S3 + 0.0000016·S3² − 0.0002574·edad","coefficients":{"constant":1.10938,"linear":-0.0008267,"quadratic":0.0000016,"age":-0.0002574}},"applicability":{"sexes":["male"],"ageMin":18,"ageMax":61,"population":"Hombres adultos del estudio generalizado original."}},
      {"code":"female","name":"Femenina · tríceps, suprailíaco y muslo anterior","appliesWhen":{"equationSex":"female"},"inputs":[{"key":"triceps","label":"Pliegue tricipital","source":"consultation_measurement","measurementCode":"triceps_skinfold","expectedUnit":"mm"},{"key":"suprailiac","label":"Pliegue suprailíaco","source":"consultation_measurement","measurementCode":"suprailiac_skinfold","expectedUnit":"mm"},{"key":"thigh","label":"Pliegue de muslo anterior","source":"consultation_measurement","measurementCode":"thigh_skinfold","expectedUnit":"mm"}],"equation":{"expression":"D = 1.0994921 − 0.0009929·S3 + 0.0000023·S3² − 0.0001392·edad","coefficients":{"constant":1.0994921,"linear":-0.0009929,"quadratic":0.0000023,"age":-0.0001392}},"applicability":{"sexes":["female"],"ageMin":18,"ageMax":55,"population":"Mujeres adultas del estudio generalizado original; cautela en mayores de 40 años según la publicación."}}
    ],
    "applicability":{"sexes":["male","female"],"ageMin":18,"ageMax":61,"population":"Adultos de los estudios generalizados originales; los límites específicos cambian por sexo.","exclusions":["No extrapolar a menores, gestación u otras poblaciones sin validación."]},
    "references":[{"authors":"Jackson AS, Pollock ML","year":1978,"title":"Generalized equations for predicting body density of men","source":"British Journal of Nutrition","doi":"10.1079/BJN19780152","url":"https://www.cambridge.org/core/journals/british-journal-of-nutrition/article/generalized-equations-for-predicting-body-density-of-men/EAB21B1CF3A8360E5F5D43FDB8D4DD17","evidence":"original"},{"authors":"Jackson AS, Pollock ML, Ward A","year":1980,"title":"Generalized equations for predicting body density of women","source":"Medicine and Science in Sports and Exercise","url":"https://pubmed.ncbi.nlm.nih.gov/7402053/","evidence":"original"}],
    "validationStatus":"validated","validationNote":"Ambas variantes, coeficientes, sitios, unidades y rangos quedaron definidos para 5B.","methodologicalNotes":["Suprailíaco no se sustituye por supraespinal ni por cresta ilíaca.","La edad se calcula a la fecha histórica de la consulta."],"limitations":"La estimación depende de la técnica de pliegues y de la similitud con la población de derivación."
  }$json$::jsonb),
  ('density_jackson_pollock_7', '2.0.0-spec', $json${
    "catalogVersion":2,"resultKey":"body_density","resultName":"Densidad corporal","methodName":"Jackson & Pollock 7","method":"Jackson-Pollock generalizado","variant":"Siete pliegues, específica por sexo","summary":"Estima densidad corporal con siete pliegues, sexo para ecuaciones y edad histórica.","unit":"g/cm³","decimalPlaces":5,
    "inputs":[{"key":"chest","label":"Pliegue pectoral","source":"consultation_measurement","measurementCode":"chest_skinfold","expectedUnit":"mm"},{"key":"midaxillary","label":"Pliegue axilar medio","source":"consultation_measurement","measurementCode":"midaxillary_skinfold","expectedUnit":"mm"},{"key":"triceps","label":"Pliegue tricipital","source":"consultation_measurement","measurementCode":"triceps_skinfold","expectedUnit":"mm"},{"key":"subscapular","label":"Pliegue subescapular","source":"consultation_measurement","measurementCode":"subscapular_skinfold","expectedUnit":"mm"},{"key":"suprailiac","label":"Pliegue suprailíaco","source":"consultation_measurement","measurementCode":"suprailiac_skinfold","expectedUnit":"mm"},{"key":"abdominal","label":"Pliegue abdominal","source":"consultation_measurement","measurementCode":"abdominal_skinfold","expectedUnit":"mm"},{"key":"thigh","label":"Pliegue de muslo anterior","source":"consultation_measurement","measurementCode":"thigh_skinfold","expectedUnit":"mm"},{"key":"sex","label":"Sexo para ecuaciones","source":"patient_record","patientField":"equation_sex","expectedUnit":"categoría"},{"key":"age","label":"Edad en esta consulta","source":"patient_derived","derivation":"age_at_consultation","expectedUnit":"años"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"La ecuación activa depende del sexo; S7 = pectoral + axilar medio + tríceps + subescapular + suprailíaco + abdominal + muslo anterior, en mm."},
    "variants":[{"code":"male","name":"Masculina","appliesWhen":{"equationSex":"male"},"equation":{"expression":"D = 1.112 − 0.00043499·S7 + 0.00000055·S7² − 0.00028826·edad","coefficients":{"constant":1.112,"linear":-0.00043499,"quadratic":0.00000055,"age":-0.00028826}},"applicability":{"sexes":["male"],"ageMin":18,"ageMax":61,"population":"Hombres del estudio generalizado original."}},{"code":"female","name":"Femenina","appliesWhen":{"equationSex":"female"},"equation":{"expression":"D = 1.097 − 0.00046971·S7 + 0.00000056·S7² − 0.00012828·edad","coefficients":{"constant":1.097,"linear":-0.00046971,"quadratic":0.00000056,"age":-0.00012828}},"applicability":{"sexes":["female"],"ageMin":18,"ageMax":55,"population":"Mujeres del estudio generalizado original; cautela en mayores de 40 años."}}],
    "applicability":{"sexes":["male","female"],"ageMin":18,"ageMax":61,"population":"Adultos de los estudios generalizados originales; límite femenino 55 años.","exclusions":["No extrapolar a menores, gestación u otras poblaciones sin validación."]},
    "references":[{"authors":"Jackson AS, Pollock ML","year":1978,"title":"Generalized equations for predicting body density of men","source":"British Journal of Nutrition","doi":"10.1079/BJN19780152","url":"https://www.cambridge.org/core/journals/british-journal-of-nutrition/article/generalized-equations-for-predicting-body-density-of-men/EAB21B1CF3A8360E5F5D43FDB8D4DD17","evidence":"original"},{"authors":"Jackson AS, Pollock ML, Ward A","year":1980,"title":"Generalized equations for predicting body density of women","source":"Medicine and Science in Sports and Exercise","url":"https://pubmed.ncbi.nlm.nih.gov/7402053/","evidence":"original"}],
    "validationStatus":"validated","validationNote":"Sitios, ecuaciones por sexo, coeficientes, unidades y rangos definidos para 5B.","methodologicalNotes":["El código suprailíaco se conserva distinto de supraespinal y cresta ilíaca."],"limitations":"La estimación depende de la técnica de pliegues y de la población de derivación."
  }$json$::jsonb),
  ('density_durnin_womersley', '2.0.0-spec', $json${
    "catalogVersion":2,"resultKey":"body_density","resultName":"Densidad corporal","methodName":"Durnin & Womersley","method":"Durnin-Womersley","variant":"Cuatro pliegues con coeficientes por sexo y edad","summary":"Estima densidad corporal a partir del logaritmo decimal de cuatro pliegues y una tabla de coeficientes por sexo y edad.","unit":"g/cm³","decimalPlaces":5,
    "inputs":[{"key":"biceps","label":"Pliegue bicipital","source":"consultation_measurement","measurementCode":"biceps_skinfold","expectedUnit":"mm"},{"key":"triceps","label":"Pliegue tricipital","source":"consultation_measurement","measurementCode":"triceps_skinfold","expectedUnit":"mm"},{"key":"subscapular","label":"Pliegue subescapular","source":"consultation_measurement","measurementCode":"subscapular_skinfold","expectedUnit":"mm"},{"key":"suprailiac","label":"Pliegue suprailíaco","source":"consultation_measurement","measurementCode":"suprailiac_skinfold","expectedUnit":"mm"},{"key":"sex","label":"Sexo para ecuaciones","source":"patient_record","patientField":"equation_sex","expectedUnit":"categoría"},{"key":"age","label":"Edad en esta consulta","source":"patient_derived","derivation":"age_at_consultation","expectedUnit":"años"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"D = c − m·log10(S4), donde S4 = bíceps + tríceps + subescapular + suprailíaco (mm).","variables":{"c":"Intercepto según sexo y grupo etario","m":"Pendiente según sexo y grupo etario"}},
    "variants":[
      {"code":"male_17_19","name":"Masculina 17–19","appliesWhen":{"equationSex":"male","ageMin":17,"ageMax":19},"equation":{"expression":"D = 1.1620 − 0.0630·log10(S4)","coefficients":{"c":1.162,"m":0.063}}},
      {"code":"male_20_29","name":"Masculina 20–29","appliesWhen":{"equationSex":"male","ageMin":20,"ageMax":29},"equation":{"expression":"D = 1.1631 − 0.0632·log10(S4)","coefficients":{"c":1.1631,"m":0.0632}}},
      {"code":"male_30_39","name":"Masculina 30–39","appliesWhen":{"equationSex":"male","ageMin":30,"ageMax":39},"equation":{"expression":"D = 1.1422 − 0.0544·log10(S4)","coefficients":{"c":1.1422,"m":0.0544}}},
      {"code":"male_40_49","name":"Masculina 40–49","appliesWhen":{"equationSex":"male","ageMin":40,"ageMax":49},"equation":{"expression":"D = 1.1620 − 0.0700·log10(S4)","coefficients":{"c":1.162,"m":0.07}}},
      {"code":"male_50_72","name":"Masculina 50–72","appliesWhen":{"equationSex":"male","ageMin":50,"ageMax":72},"equation":{"expression":"D = 1.1715 − 0.0779·log10(S4)","coefficients":{"c":1.1715,"m":0.0779}}},
      {"code":"female_16_19","name":"Femenina 16–19","appliesWhen":{"equationSex":"female","ageMin":16,"ageMax":19},"equation":{"expression":"D = 1.1549 − 0.0678·log10(S4)","coefficients":{"c":1.1549,"m":0.0678}}},
      {"code":"female_20_29","name":"Femenina 20–29","appliesWhen":{"equationSex":"female","ageMin":20,"ageMax":29},"equation":{"expression":"D = 1.1599 − 0.0717·log10(S4)","coefficients":{"c":1.1599,"m":0.0717}}},
      {"code":"female_30_39","name":"Femenina 30–39","appliesWhen":{"equationSex":"female","ageMin":30,"ageMax":39},"equation":{"expression":"D = 1.1423 − 0.0632·log10(S4)","coefficients":{"c":1.1423,"m":0.0632}}},
      {"code":"female_40_49","name":"Femenina 40–49","appliesWhen":{"equationSex":"female","ageMin":40,"ageMax":49},"equation":{"expression":"D = 1.1333 − 0.0612·log10(S4)","coefficients":{"c":1.1333,"m":0.0612}}},
      {"code":"female_50_68","name":"Femenina 50–68","appliesWhen":{"equationSex":"female","ageMin":50,"ageMax":68},"equation":{"expression":"D = 1.1339 − 0.0645·log10(S4)","coefficients":{"c":1.1339,"m":0.0645}}}
    ],
    "applicability":{"sexes":["male","female"],"ageMin":16,"ageMax":72,"population":"481 hombres y mujeres estudiados originalmente; rangos efectivos: hombres 17–72, mujeres 16–68.","exclusions":["Fuera del rango específico no se selecciona coeficiente."]},
    "references":[{"authors":"Durnin JVGA, Womersley J","year":1974,"title":"Body fat assessed from total body density and its estimation from skinfold thickness","source":"British Journal of Nutrition","doi":"10.1079/BJN19740060","url":"https://www.cambridge.org/core/journals/british-journal-of-nutrition/article/body-fat-assessed-from-total-body-density-and-its-estimation-from-skinfold-thickness-measurements-on-481-men-and-women-aged-from-16-to-72-years/DAC8BA25856FCEB30E22F60E0AF80D07","evidence":"original"}],
    "validationStatus":"validated","validationNote":"Tabla etaria completa, transformación log10, sitios y unidades definidos para 5B.","methodologicalNotes":["Se usarán los grupos por edad, no la ecuación agregada de todas las edades."],"limitations":"La densidad estimada conserva las limitaciones de la muestra y de la técnica de medición original."
  }$json$::jsonb)
) as v(code, method_version, definition)
where c.code = v.code;

update public.calculation_definitions as c
set method_version = v.method_version,
    definition = v.definition,
    updated_at = now()
from (values
  ('muscle_mass_lee', '2.0.0-spec', $json${
    "catalogVersion":2,"resultKey":"muscle_mass","resultName":"Masa muscular esquelética","methodName":"Lee","method":"Lee et al. 2000","variant":"Modelo 1 antropométrico · candidato","summary":"Modelo antropométrico de masa muscular esquelética con circunferencias corregidas, talla, sexo, edad y término poblacional.","unit":"kg","decimalPlaces":1,
    "inputs":[{"key":"height","label":"Estatura","source":"patient_record","patientField":"height_cm","expectedUnit":"cm"},{"key":"arm_girth","label":"Circunferencia de brazo relajado","source":"consultation_measurement","measurementCode":"relaxed_arm_circumference","expectedUnit":"cm"},{"key":"triceps","label":"Pliegue tricipital","source":"consultation_measurement","measurementCode":"triceps_skinfold","expectedUnit":"mm"},{"key":"mid_thigh_girth","label":"Circunferencia de muslo medio","source":"consultation_measurement","measurementCode":"mid_thigh_circumference","expectedUnit":"cm"},{"key":"thigh_skinfold","label":"Pliegue de muslo anterior","source":"consultation_measurement","measurementCode":"thigh_skinfold","expectedUnit":"mm"},{"key":"calf_girth","label":"Circunferencia máxima de pantorrilla","source":"consultation_measurement","measurementCode":"calf_circumference","expectedUnit":"cm"},{"key":"calf_skinfold","label":"Pliegue de pantorrilla medial","source":"consultation_measurement","measurementCode":"calf_skinfold","expectedUnit":"mm"},{"key":"sex","label":"Sexo para ecuaciones","source":"patient_record","patientField":"equation_sex","expectedUnit":"categoría"},{"key":"age","label":"Edad en esta consulta","source":"patient_derived","derivation":"age_at_consultation","expectedUnit":"años"},{"key":"population_group","label":"Grupo poblacional del modelo Lee","source":"patient_record","patientField":"lee_population_group","expectedUnit":"categoría"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"MM = talla_m·(0.00744·CAG² + 0.00088·CTG² + 0.00441·CCG²) + 2.4·sexo − 0.048·edad + grupo + 7.8","variables":{"CAG":"brazo_relajado_cm − π·(tríceps_mm/10)","CTG":"muslo_medio_cm − π·(muslo_mm/10)","CCG":"pantorrilla_máxima_cm − π·(pantorrilla_mm/10)","sexo":"0 mujer, 1 hombre","grupo":"−2.0 asiático, +1.1 afroamericano, 0 blanco o hispano"},"coefficients":{"arm":0.00744,"thigh":0.00088,"calf":0.00441,"sex":2.4,"age":-0.048,"constant":7.8},"transformations":["Convertir talla de cm a m","Convertir cada pliegue de mm a cm antes de multiplicar por π"]},"variants":[{"code":"model_2","name":"Modelo 2 peso-talla · documentado pero no adoptado","inputs":[{"key":"weight","label":"Peso","source":"consultation_measurement","measurementCode":"weight","expectedUnit":"kg"},{"key":"height","label":"Estatura","source":"patient_record","patientField":"height_cm","expectedUnit":"cm"},{"key":"sex","label":"Sexo para ecuaciones","source":"patient_record","patientField":"equation_sex","expectedUnit":"categoría"},{"key":"age","label":"Edad en esta consulta","source":"patient_derived","derivation":"age_at_consultation","expectedUnit":"años"},{"key":"population_group","label":"Grupo poblacional del modelo Lee","source":"patient_record","patientField":"lee_population_group","expectedUnit":"categoría"}],"equation":{"expression":"MM = 0.244·peso_kg + 7.80·talla_m + 6.6·sexo − 0.098·edad + grupo − 3.3"},"note":"Menor ajuste que el modelo 1 en el estudio original; no seleccionado."}],
    "applicability":{"sexes":["male","female"],"population":"Adultos sanos no obesos (IMC < 30 kg/m²) de la muestra original.","exclusions":["No extrapolar automáticamente a IMC ≥30 ni fuera de los grupos del modelo."]},
    "references":[{"authors":"Lee RC, Wang Z, Heo M, Ross R, Janssen I, Heymsfield SB","year":2000,"title":"Total-body skeletal muscle mass: development and cross-validation of anthropometric prediction models","source":"American Journal of Clinical Nutrition","doi":"10.1093/ajcn/72.3.796","url":"https://pubmed.ncbi.nlm.nih.gov/10966902/","evidence":"original"}],
    "validationStatus":"requires_decision","validationNote":"La ecuación está definida, pero el expediente no dispone de un campo éticamente y semánticamente acordado para el término poblacional del modelo; no se asumirá valor 0.","methodologicalNotes":["Se propone el modelo 1 por su mayor ajuste original, sujeto a aprobar el modelado del término poblacional.","Brazo relajado, muslo medio y pantorrilla máxima son sitios distintos de otros perímetros."],"limitations":"SEE original 2.2 kg; variable poblacional histórica y aplicación sólo en adultos no obesos requieren decisión explícita."
  }$json$::jsonb),
  ('somatotype_endomorphy', '2.0.0-spec', $json${
    "catalogVersion":2,"resultKey":"endomorphy","resultName":"Endomorfia","methodName":"Endomorfia · Heath-Carter","method":"Somatotipo antropométrico Heath-Carter","variant":"Componente endomórfico corregido por talla","summary":"Calcula el componente endomórfico con tríceps, subescapular y supraespinal corregidos por talla.","unit":"componente","decimalPlaces":1,
    "inputs":[{"key":"triceps","label":"Pliegue tricipital","source":"consultation_measurement","measurementCode":"triceps_skinfold","expectedUnit":"mm"},{"key":"subscapular","label":"Pliegue subescapular","source":"consultation_measurement","measurementCode":"subscapular_skinfold","expectedUnit":"mm"},{"key":"supraspinale","label":"Pliegue supraespinal","source":"consultation_measurement","measurementCode":"supraespinale_skinfold","expectedUnit":"mm"},{"key":"height","label":"Estatura","source":"patient_record","patientField":"height_cm","expectedUnit":"cm"}],"optionalInputs":[],"dependencies":[],
    "equation":{"expression":"X=(tríceps+subescapular+supraespinal)·(170.18/talla_cm); endomorfia=−0.7182+0.1451·X−0.00068·X²+0.0000014·X³","conditions":["Si el componente calculado es ≤0, asignar 0.1"]},"variants":[],"applicability":{"population":"Método antropométrico Heath-Carter; requiere mediciones realizadas con sitios consistentes."},
    "references":[{"authors":"Carter JEL","year":2002,"title":"The Heath-Carter Anthropometric Somatotype: Instruction Manual","source":"San Diego State University","url":"https://phentermineclinics.net/wp-content/uploads/2023/09/Heath-CarterManual.pdf","evidence":"technical_manual"}],
    "validationStatus":"validated","validationNote":"Inputs, corrección por talla, polinomio y regla mínima definidos para 5B.","methodologicalNotes":["Usa supraespinal, no suprailíaco ni cresta ilíaca."],"limitations":"Es un componente descriptivo del somatotipo, no una clasificación clínica."
  }$json$::jsonb),
