-- Guardrails: all 19 visible anthropometric contracts are complete enough for
-- the interface, and runtime status remains independent from validation.
do $$
declare
  incomplete_count integer;
begin
  select count(*) into incomplete_count
  from public.calculation_definitions
  where is_catalog_visible
    and (
      definition->>'catalogVersion' <> '2'
      or definition->>'validationStatus' not in ('validated','requires_decision','pending_evidence')
      or jsonb_typeof(definition->'inputs') <> 'array'
      or jsonb_typeof(definition->'optionalInputs') <> 'array'
      or jsonb_typeof(definition->'dependencies') <> 'array'
      or jsonb_typeof(definition->'equation') <> 'object'
      or jsonb_typeof(definition->'applicability') <> 'object'
      or jsonb_typeof(definition->'references') <> 'array'
    );
  if incomplete_count <> 0 then
    raise exception 'Objective 5A left % visible calculation contracts incomplete', incomplete_count;
  end if;
end;
$$;
